import React, { useState, useEffect } from 'react';
import { getPatients, createPatient, updatePatient, deletePatient, searchPatients } from '../services/api';
import './Pages.css';

const formatPhoneInput = (value) => value.replace(/\D/g, '').slice(0, 9);
const formatMedicalNumberInput = (value) => value.replace(/\D/g, '').slice(0, 12);

const validatePatientForm = ({ medicalNumber, firstName, lastName, birthDate, phone }) => {
  if (!medicalNumber || !firstName || !lastName || !birthDate || !phone) {
    return 'Todos los campos obligatorios deben estar completos.';
  }
  if (!/^[0-9]{4,12}$/.test(medicalNumber)) {
    return 'Número médico inválido. Debe contener solo dígitos, sin espacios ni letras.';
  }
  if (!/^[0-9]{9}$/.test(phone)) {
    return 'Teléfono inválido. Debe contener exactamente 9 dígitos.';
  }
  return null;
};

export default function Patients() {
  const [patients, setPatients] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState('');
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    medicalNumber: '',
    firstName: '',
    lastName: '',
    birthDate: '',
    phone: '',
    address: '',
    city: ''
  });
  const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

  useEffect(() => {
    fetchPatients();
  }, []);

  const fetchPatients = async () => {
    try {
      const res = await getPatients();
      setPatients(res.data);
      setStatusMessage({ type: '', text: '' });
    } catch (err) {
      console.error('Error al cargar pacientes:', err.response?.data || err.message);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'No se pueden cargar los pacientes. Vuelve a iniciar sesión si es necesario.'
      });
    }
  };

  const handleSearch = async () => {
    if (!search) {
      fetchPatients();
      return;
    }
    try {
      const res = await searchPatients(search);
      setPatients(res.data);
      setStatusMessage({ type: '', text: '' });
    } catch (err) {
      console.error('Error buscando pacientes:', err.response?.data || err.message);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'No se pudo buscar pacientes.'
      });
    }
  };

  const resetForm = () => {
    setEditing(null);
    setForm({
      medicalNumber: '',
      firstName: '',
      lastName: '',
      birthDate: '',
      phone: '',
      address: '',
      city: ''
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationError = validatePatientForm(form);
    if (validationError) {
      setStatusMessage({ type: 'error', text: validationError });
      return;
    }

    try {
      const payload = {
        medicalNumber: form.medicalNumber.trim(),
        firstName: form.firstName.trim(),
        lastName: form.lastName.trim(),
        birthDate: form.birthDate,
        phone: form.phone.trim(),
        address: form.address.trim(),
        city: form.city.trim(),
        state: form.state?.trim() || '',
        postalCode: form.postalCode?.trim() || ''
      };

      if (editing) {
        await updatePatient(editing, payload);
        setStatusMessage({ type: 'success', text: 'Paciente actualizado correctamente.' });
      } else {
        await createPatient(payload);
        setStatusMessage({ type: 'success', text: 'Paciente creado correctamente.' });
      }

      resetForm();
      setShowForm(false);
      fetchPatients();
      setTimeout(() => setStatusMessage({ type: '', text: '' }), 4000);
    } catch (err) {
      console.error('Error:', err);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'Error al guardar paciente. Revisa los datos e intenta de nuevo.'
      });
    }
  };

  const handleEdit = (patient) => {
    setEditing(patient.id);
    setForm({
      medicalNumber: patient.medicalNumber,
      firstName: patient.firstName,
      lastName: patient.lastName,
      birthDate: patient.birthDate || '',
      phone: patient.phone,
      address: patient.address || '',
      city: patient.city || ''
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Estás seguro?')) {
      try {
        await deletePatient(id);
        fetchPatients();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  return (
    <div className="page">
      <div className="page-header">
        <h2>👥 Gestión de Pacientes</h2>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn-primary">
          {showForm ? 'Cancelar' : editing ? 'Editar Paciente' : '+ Nuevo Paciente'}
        </button>
      </div>

      <div className="search-bar">
        <input
          type="text"
          placeholder="Buscar paciente..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
        />
        <button type="button" onClick={handleSearch}>Buscar</button>
      </div>

      {statusMessage.text && (
        <div className={`status-message ${statusMessage.type}`}>
          {statusMessage.text}
        </div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <input
            type="text"
            placeholder="Número Médico"
            inputMode="numeric"
            maxLength={12}
            value={form.medicalNumber}
            onChange={(e) => setForm({ ...form, medicalNumber: formatMedicalNumberInput(e.target.value) })}
            required
          />
          <input
            type="text"
            placeholder="Nombre"
            value={form.firstName}
            onChange={(e) => setForm({ ...form, firstName: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Apellido"
            value={form.lastName}
            onChange={(e) => setForm({ ...form, lastName: e.target.value })}
            required
          />
          <input
            type="date"
            value={form.birthDate}
            onChange={(e) => setForm({ ...form, birthDate: e.target.value })}
          />
          <input
            type="tel"
            placeholder="Teléfono (9 dígitos)"
            inputMode="numeric"
            maxLength={9}
            value={form.phone}
            onChange={(e) => setForm({ ...form, phone: formatPhoneInput(e.target.value) })}
            required
          />
          <input
            type="text"
            placeholder="Dirección"
            value={form.address}
            onChange={(e) => setForm({ ...form, address: e.target.value })}
          />
          <input
            type="text"
            placeholder="Ciudad"
            value={form.city}
            onChange={(e) => setForm({ ...form, city: e.target.value })}
          />
          <button type="submit" className="btn-success">{editing ? 'Actualizar' : 'Guardar'}</button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Número</th>
            <th>Nombre</th>
            <th>Apellido</th>
            <th>Teléfono</th>
            <th>Ciudad</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {patients.map((p) => (
            <tr key={p.id}>
              <td>{p.medicalNumber}</td>
              <td>{p.firstName}</td>
              <td>{p.lastName}</td>
              <td>{p.phone}</td>
              <td>{p.city}</td>
              <td>
                <button className="btn-primary" onClick={() => handleEdit(p)}>Editar</button>
                <button className="btn-danger" onClick={() => handleDelete(p.id)}>Eliminar</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
